bool read(const WireValue &wire, NiriOutputAction &value, DecodeError &error, const QString &path, DecodeMode mode)
{
    QString tag;
    const WireValue *payload = nullptr;
    if (const auto *text = wire.stringValue()) tag = *text;
    else if (const auto *object = wire.objectValue(); object && object->size() == 1) {
        tag = object->first().first;
        payload = &object->first().second;
    } else return fail(error, path, QStringLiteral("expected enum string or single-key variant"));
    if (tag == QStringLiteral("CustomMode")) {
        if (!payload) return fail(error, path, QStringLiteral("expected tagged payload"));
        NiriOutputActionCustomModePayload item{};
        if (!read(*payload, item, error, childPath(path, tag), mode)) return false;
        value = NiriOutputAction::fromCustomMode(item);
        return true;
    }
    if (tag == QStringLiteral("Mode")) {
        if (!payload) return fail(error, path, QStringLiteral("expected tagged payload"));
        NiriOutputActionModePayload item{};
        if (!read(*payload, item, error, childPath(path, tag), mode)) return false;
        value = NiriOutputAction::fromMode(item);
        return true;
    }
    if (tag == QStringLiteral("Modeline")) {
        if (!payload) return fail(error, path, QStringLiteral("expected tagged payload"));
        NiriOutputActionModelinePayload item{};
        if (!read(*payload, item, error, childPath(path, tag), mode)) return false;
        value = NiriOutputAction::fromModeline(item);
        return true;
    }
    if (tag == QStringLiteral("Off")) {
        if (payload) return fail(error, path, QStringLiteral("expected unit string"));
        value = NiriOutputAction::fromOff();
        return true;
    }
    if (tag == QStringLiteral("On")) {
        if (payload) return fail(error, path, QStringLiteral("expected unit string"));
        value = NiriOutputAction::fromOn();
        return true;
    }
    if (tag == QStringLiteral("Position")) {
        if (!payload) return fail(error, path, QStringLiteral("expected tagged payload"));
        NiriOutputActionPositionPayload item{};
        if (!read(*payload, item, error, childPath(path, tag), mode)) return false;
        value = NiriOutputAction::fromPosition(item);
        return true;
    }
    if (tag == QStringLiteral("Scale")) {
        if (!payload) return fail(error, path, QStringLiteral("expected tagged payload"));
        NiriOutputActionScalePayload item{};
        if (!read(*payload, item, error, childPath(path, tag), mode)) return false;
        value = NiriOutputAction::fromScale(item);
        return true;
    }
    if (tag == QStringLiteral("Transform")) {
        if (!payload) return fail(error, path, QStringLiteral("expected tagged payload"));
        NiriOutputActionTransformPayload item{};
        if (!read(*payload, item, error, childPath(path, tag), mode)) return false;
        value = NiriOutputAction::fromTransform(item);
        return true;
    }
    if (tag == QStringLiteral("Vrr")) {
        if (!payload) return fail(error, path, QStringLiteral("expected tagged payload"));
        NiriOutputActionVrrPayload item{};
        if (!read(*payload, item, error, childPath(path, tag), mode)) return false;
        value = NiriOutputAction::fromVrr(item);
        return true;
    }
    if (mode == DecodeMode::Outbound) return fail(error, path, QStringLiteral("unknown variant"));
    NiriOutputAction result;
    result.value = NiriUnknownVariant{tag, wire};
    value = result;
    return true;
}
bool write(const NiriOutputAction &value, WireValue &wire, DecodeError &error, const QString &path)
{
    switch (value.kind()) {
    case NiriOutputAction::CustomMode: {
        WireValue payload;
        const auto tag = QStringLiteral("CustomMode");
        if (!write(std::get<NiriOutputAction::CustomModeValue>(value.value).payload, payload, error, childPath(path, tag))) return false;
        wire = *WireValue::object({{tag, payload}});
        return true;
    }
    case NiriOutputAction::Mode: {
        WireValue payload;
        const auto tag = QStringLiteral("Mode");
        if (!write(std::get<NiriOutputAction::ModeValue>(value.value).payload, payload, error, childPath(path, tag))) return false;
        wire = *WireValue::object({{tag, payload}});
        return true;
    }
    case NiriOutputAction::Modeline: {
        WireValue payload;
        const auto tag = QStringLiteral("Modeline");
        if (!write(std::get<NiriOutputAction::ModelineValue>(value.value).payload, payload, error, childPath(path, tag))) return false;
        wire = *WireValue::object({{tag, payload}});
        return true;
    }
    case NiriOutputAction::Off: {
        wire = WireValue(QStringLiteral("Off"));
        return true;
    }
    case NiriOutputAction::On: {
        wire = WireValue(QStringLiteral("On"));
        return true;
    }
    case NiriOutputAction::Position: {
        WireValue payload;
        const auto tag = QStringLiteral("Position");
        if (!write(std::get<NiriOutputAction::PositionValue>(value.value).payload, payload, error, childPath(path, tag))) return false;
        wire = *WireValue::object({{tag, payload}});
        return true;
    }
    case NiriOutputAction::Scale: {
        WireValue payload;
        const auto tag = QStringLiteral("Scale");
        if (!write(std::get<NiriOutputAction::ScaleValue>(value.value).payload, payload, error, childPath(path, tag))) return false;
        wire = *WireValue::object({{tag, payload}});
        return true;
    }
    case NiriOutputAction::Transform: {
        WireValue payload;
        const auto tag = QStringLiteral("Transform");
        if (!write(std::get<NiriOutputAction::TransformValue>(value.value).payload, payload, error, childPath(path, tag))) return false;
        wire = *WireValue::object({{tag, payload}});
        return true;
    }
    case NiriOutputAction::Vrr: {
        WireValue payload;
        const auto tag = QStringLiteral("Vrr");
        if (!write(std::get<NiriOutputAction::VrrValue>(value.value).payload, payload, error, childPath(path, tag))) return false;
        wire = *WireValue::object({{tag, payload}});
        return true;
    }
    case NiriOutputAction::Unknown: wire = std::get<NiriUnknownVariant>(value.value).raw; return true;
    default: return fail(error, path, value.invalidReason.isEmpty() ? QStringLiteral("invalid union construction") : value.invalidReason);
    }
}

